// Mini framework de juguete: NO es para usar en serio, es para ver la idea.
function crearApp({ raiz, estado, vista, acciones }) {
  let actual = estado;                       // el estado vive acá adentro
  const dibujar = () => { raiz.innerHTML = vista(actual); };

  const app = {
    leer: () => actual,
    cambiar(f) {                             // única puerta para modificar el estado
      actual = f(actual);                    // f recibe el estado viejo y devuelve uno nuevo
      dibujar();                             // y la pantalla se rehace sola
    },
  };

  // una sola oreja en la raíz: los elementos con data-accion avisan qué hacer
  raiz.addEventListener("click", (e) => {
    const el = e.target.closest("[data-accion]");
    if (el) acciones[el.dataset.accion](app, el.dataset.id);
  });

  dibujar();
  return app;
}

