  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// La vista es una función pura: recibe el estado y devuelve el HTML completo de la lista.
function vista(estado) {
  const pendientes = estado.tareas.filter((t) => !t.hecha).length;
  const filas = estado.tareas.map((t) => `
    <li class="${t.hecha ? "hecha" : ""}">
      <input type="checkbox" data-accion="tildar" data-id="${t.id}" ${t.hecha ? "checked" : ""}>
      <span>${esc(t.texto)}</span>
      <button data-accion="borrar" data-id="${t.id}">x</button>
    </li>`).join("");
  return `<ul>${filas}</ul><p>Pendientes: ${pendientes} de ${estado.tareas.length}</p>`;
}

const acciones = {
  tildar: (app, id) => app.cambiar((s) => ({ ...s,
    tareas: s.tareas.map((t) => (t.id === Number(id) ? { ...t, hecha: !t.hecha } : t)) })),
  borrar: (app, id) => app.cambiar((s) => ({ ...s,
    tareas: s.tareas.filter((t) => t.id !== Number(id)) })),
};

// Mini framework de juguete, probado con una «raíz» falsa (en el Worker no hay DOM).
